contrasting.source:
language "moriarty/1";
agreement CounterflowCollection {
  asset QA = { network: "local", issuer: "signed-native-qa", reference: "QA", scale: 0 };
  state collected: UInt = 0;
  state frozen: Bool = true;
  action originate() {
    liability("payment", QA, "alice", "carol", 12);
    liability("reserve", QA, "alice", "auditor", 5);
    liability("zero", QA, "alice", "auditor", 0);
  }
  action collect(amount: UInt) {
    requires amount == 43;
    fee(QA, "alice", "treasury", 3);
    transfer(QA, "alice", "carol", amount - 3);
    liability("addon", QA, "alice", "auditor", 4);
    discharge("payment", 7);
    next collected = collected + amount - 3;
    emit "collected"(collected);
    ensures frozen and collected == 40;
  }
}
